    Empty,
    InvalidChar { value: string, offset: i64 },
    Overflow,
}

fn fetchUser(id: i64) throws(HttpErr) -> User {
    if (id <= 0) { throw HttpErr.NotFound { message: "user not found" } }
    // ...
}

