009-8-error-handling-example-019.code:
fn fetch(url: string) throws(IoErr | FetchErr) -> string {
    var conn = try open(url)
    defer { conn.close() }                   // 无论后续如何，conn 一定关闭

    var data = try conn.read()
    if (len(data) == 0) {
        throw FetchErr.Empty                 // defer 仍执行
    }
    return data
}

